INSERT INTO "messages" VALUES(7,'20260927_141754_17bd65','tool','{"content": "1|def add(a, b):\n2|    return a + b\n3|\n4|\n5|def average(values):\n6|    if not values:\n7|        return 0\n8|    return sum(values) / (len(values) - 1)\n9|", "total_lines": 8, "file_size": 134, "truncated": false, "is_binary": false, "is_image": false}','call_vsCKZ5xnel6cyK8goojB2CQG',NULL,'read_file',NULL,1.790489898800624848e+09,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,1,0,NULL,NULL,NULL);
